package com.vividlands.village;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;

import net.minecraft.util.RandomSource;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Village building lists by style and role, generated by tools/structures
 * (vividlands_villages/catalogue.json).
 */
public final class VillageCatalogue {
    private static Map<String, VillageCatalogue> styles;
    private final Map<String, List<String>> byRole = new HashMap<>();

    private VillageCatalogue() {
    }

    private static Map<String, VillageCatalogue> load() {
        Map<String, VillageCatalogue> out = new HashMap<>();
        try (InputStream in = VillageCatalogue.class.getResourceAsStream("/vividlands_villages/catalogue.json")) {
            if (in == null) {
                throw new IllegalStateException("missing catalogue");
            }
            for (JsonElement e : JsonParser.parseReader(new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonArray()) {
                JsonObject o = e.getAsJsonObject();
                String style = o.has("style") ? o.get("style").getAsString() : "north";
                out.computeIfAbsent(style, k -> new VillageCatalogue()).byRole
                        .computeIfAbsent(o.get("role").getAsString(), k -> new ArrayList<>()).add(o.get("id").getAsString());
            }
        } catch (Exception ex) {
            VividLandsVikings.LOG.error("Could not load the village catalogue", ex);
        }
        return out;
    }

    public static synchronized VillageCatalogue get(VillageStyle style) {
        if (styles == null) {
            styles = load();
        }
        VillageCatalogue c = styles.get(style.id);
        return c != null ? c : styles.getOrDefault("north", new VillageCatalogue());
    }

    public List<String> all(String role) {
        return new ArrayList<>(byRole.getOrDefault(role, List.of()));
    }

    public String pick(String role, RandomSource rand) {
        List<String> l = byRole.getOrDefault(role, List.of());
        return l.get(rand.nextInt(l.size()));
    }

    public List<String> pickSome(String role, int n, RandomSource rand) {
        List<String> l = all(role);
        List<String> out = new ArrayList<>();
        for (int i = 0; i < n && !l.isEmpty(); i++) {
            out.add(l.remove(rand.nextInt(l.size())));
        }
        return out;
    }
}
